assert solve([], 6) == Report(0, 0, 6), 'fixture 15'
assert solve([Entry(1, 16, 1)], 7) == Report(0, 0, 8), 'fixture 16'
assert solve([Entry(2, 11, 4), Entry(1, 28, 2)], 8) == Report(0, 0, 11), 'fixture 17'
assert solve([Entry(8, 23, 3), Entry(5, 21, 1), Entry(3, 19, 1)], 1) == Report(0, 0, 17), 'fixture 18'
assert solve([Entry(4, 18, 2), Entry(4, 7, 3), Entry(1, 22, 2), Entry(8, 16, 1)], 2) == Report(2, 12, 19), 'fixture 19'
