assert solve([Entry(3, 3, 3), Entry(3, 4, 2), Entry(6, 9, 4), Entry(1, 7, 4), Entry(7, 2, 3), Entry(3, 0, 4)], 4) == Report(6, 266, 27), 'fixture 21'
